import { BrowserRouter as Router, Routes, Route } from "react-router-dom";
import Home from "@/pages/Home";
import ThemeApplier from "@/theme/ThemeApplier";
import FloatingPhone from "@/components/FloatingPhone";
import FloatingMusic from "@/components/FloatingMusic";
import MusicPlayerModal from "@/components/MusicPlayerModal";
import DriftBottleModal from "@/components/modals/DriftBottleModal";
import ErrorBoundary from "@/components/ErrorBoundary";
import MsgNotificationToasts from "@/components/MsgNotificationToasts";
import { useEffect, useRef, useState } from "react";
import { useAppStore } from "@/store/app";

const basename = import.meta.env.BASE_URL;
const NOTIFICATION_ICON = "https://i.postimg.cc/ZKVRS4kH/retouch-2026071501420750.png";

const DRIFT_BOTTLE_IMAGES = [
  "driftbottle/bg.jpg",
  "driftbottle/coral.png",
  "driftbottle/pearl.png",
  "driftbottle/shell.png",
  "driftbottle/wave.png",
  "driftbottle/star.png",
  "driftbottle/envelope.png",
  "driftbottle/letter.jpg",
  "driftbottle/diary.jpg",
];

export default function App() {
  const [notificationGranted, setNotificationGranted] = useState(false);
  const beauty = useAppStore((s) => s.beauty);
  const pushNotification = useAppStore((s) => s.chat.pushNotification);
  const lastMsgIdRef = useRef<string | null>(null);
  const lastMemoIdRef = useRef<string | null>(null);
  // 应用内弹窗：跟踪每个会话最后见过的消息ID
  const seenMsgIdsRef = useRef<Map<string, string>>(new Map());
  const inAppToastInitRef = useRef(false);

  useEffect(() => {
    if ("Notification" in window) {
      Notification.requestPermission().then((permission) => {
        setNotificationGranted(permission === "granted");
      });
    }
  }, []);

  useEffect(() => {
    const handleVisibilityChange = () => {
      if (document.hidden && notificationGranted && pushNotification) {
        document.title = "💬 苜蓿 · 有新消息";
      } else {
        document.title = "苜蓿";
      }
    };

    document.addEventListener("visibilitychange", handleVisibilityChange);
    return () => {
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, [notificationGranted, pushNotification]);

  useEffect(() => {
    const checkNewMessage = () => {
      if (!notificationGranted || !document.hidden || !pushNotification) return;

      const state = useAppStore.getState();
      const activeConv = state.conversations.find((c) => c.id === state.activeConversationId);
      const messages = activeConv?.messages || [];
      const lastMsg = messages[messages.length - 1];
      if (!lastMsg || lastMsg.id === lastMsgIdRef.current) return;
      lastMsgIdRef.current = lastMsg.id;

      if (lastMsg.type === "system") {
        new Notification("苜蓿", {
          body: lastMsg.systemText,
          icon: NOTIFICATION_ICON,
        });
      } else if (lastMsg.sender !== "me" && lastMsg.text) {
        const senderName = lastMsg.sender === "her"
          ? beauty.herName
          : state.contacts.find((c) => c.id === lastMsg.sender)?.name || "对方";
        new Notification(`${senderName} 回复了你的消息`, {
          body: lastMsg.text.substring(0, 100),
          icon: NOTIFICATION_ICON,
        });
      }
    };

    const checkNewMemo = () => {
      if (!notificationGranted || !document.hidden || !pushNotification) return;

      const state = useAppStore.getState();
      const latest = state.memos[0];
      if (!latest || latest.id === lastMemoIdRef.current) return;
      lastMemoIdRef.current = latest.id;

      if (latest.from === "me") return;
      if (Date.now() - latest.timestamp > 10000) return;

      const senderName =
        state.contacts.find((c) => c.id === latest.from)?.name || beauty.herName;
      new Notification(`${senderName} 给你发来一封信`, {
        body: latest.text.substring(0, 100),
        icon: NOTIFICATION_ICON,
      });
    };

    const unsubscribe = useAppStore.subscribe(() => {
      checkNewMessage();
      checkNewMemo();
    });

    return unsubscribe;
  }, [notificationGranted, beauty.herName, pushNotification]);

  useEffect(() => {
    DRIFT_BOTTLE_IMAGES.forEach((path) => {
      const img = new Image();
      img.src = `${basename}${path}`;
    });
  }, []);

  // 应用内新消息弹窗：监听所有会话的新消息（来自对方/群成员）
  useEffect(() => {
    const buildPreview = (msg: any): string => {
      switch (msg.type) {
        case "text": return msg.text || "";
        case "image": return "[图片]";
        case "sticker": return "[表情包]";
        case "card": return `[卡片] ${msg.card?.content?.slice?.(0, 24) || ""}`.trim();
        case "note": return `[小纸条] ${msg.noteMood || ""} ${(msg.moodNote || msg.text || "").slice(0, 24)}`.trim();
        case "redpacket": return msg.redpacket?.message ? `[红包] ${msg.redpacket.message}` : "[红包] 恭喜发财，大吉大利";
        case "shop": return msg.shop ? `[礼物] ${msg.shop.emoji || "🎁"} ${msg.shop.productName || ""}`.trim() : "[礼物]";
        case "music": return `[音乐] ${msg.music?.title || ""}`.trim();
        case "rps": return msg.rps?.resolved ? "[猜拳] 已出结果" : "[猜拳] 来猜拳吧！";
        case "poll": return msg.poll ? `[投票] ${msg.poll.question}`.slice(0, 32) : "[投票]";
        case "survey": return "[问卷]";
        case "flychess": return "[飞行棋]";
        default: return msg.text || "[新消息]";
      }
    };

    // 延迟初始化：等持久化数据完全恢复后（1.2s）再记录当前消息ID，避免误弹旧消息
    let initTimer: ReturnType<typeof setTimeout> | null = null;

    const tryInit = () => {
      if (inAppToastInitRef.current) return;
      const st = useAppStore.getState();
      // 必须至少有一条消息才算初始化完成（IDB 持久化数据已恢复）
      const hasMsgs = st.conversations.some((c) => c.messages.length > 0);
      if (!hasMsgs) {
        // 没有消息也视为已初始化
      }
      st.conversations.forEach((c) => {
        const last = c.messages[c.messages.length - 1];
        if (last) seenMsgIdsRef.current.set(c.id, last.id);
      });
      inAppToastInitRef.current = true;
      if (initTimer) {
        clearTimeout(initTimer);
        initTimer = null;
      }
    };

    initTimer = setTimeout(tryInit, 1200);

    const checkInAppToast = () => {
      // 未初始化前不弹（避免恢复持久化数据时狂弹旧消息）
      if (!inAppToastInitRef.current) {
        tryInit();
        return;
      }

      const st = useAppStore.getState();
      st.conversations.forEach((conv) => {
        const last = conv.messages[conv.messages.length - 1];
        if (!last) return;
        const seen = seenMsgIdsRef.current.get(conv.id);
        if (seen === last.id) return; // 没有新消息
        seenMsgIdsRef.current.set(conv.id, last.id);

        // 只处理来自对方/群成员的消息（我发的不弹、系统消息不弹）
        if (last.sender === "me") return;
        if (last.type === "system") return;

        // 如果消息已经超过 10 秒，不弹（可能是持久化恢复的旧数据）
        if (Date.now() - last.timestamp > 10 * 1000) return;

        const isGroup = conv.type === "group";
        let senderName = "";
        let senderAvatarText = "?";
        let senderAvatarImage: string | undefined;

        if (isGroup) {
          const member = st.contacts.find((c) => c.id === last.sender);
          senderName = member?.name || String(last.sender);
          senderAvatarText = member?.avatar?.slice?.(0, 1) || senderName.slice(0, 1) || "群";
          senderAvatarImage = member?.avatarImage || conv.herAvatarImage || st.beauty.herAvatarImage || undefined;
        } else {
          const contact = st.contacts.find((c) => c.id === conv.memberIds[0]);
          senderName = contact?.name || st.beauty.herName || "对方";
          senderAvatarText = contact?.avatar?.slice?.(0, 1) || senderName.slice(0, 1) || "?";
          senderAvatarImage = contact?.avatarImage || conv.herAvatarImage || st.beauty.herAvatarImage || undefined;
        }

        st.pushMsgNotification({
          conversationId: conv.id,
          senderId: String(last.sender),
          senderName,
          senderAvatarText,
          senderAvatarImage,
          conversationName: conv.name || (isGroup ? "群聊" : senderName),
          isGroup,
          preview: buildPreview(last).slice(0, 48),
          messageType: last.type,
        });
      });
    };

    const unsubscribe = useAppStore.subscribe(() => {
      checkInAppToast();
    });
    return () => {
      unsubscribe();
      if (initTimer) clearTimeout(initTimer);
    };
  }, []);

  return (
    <>
      <ThemeApplier />
      <ErrorBoundary>
        <Router basename={basename}>
          <Routes>
            <Route path="/" element={<Home />} />
          </Routes>
        </Router>
      </ErrorBoundary>
      <ErrorBoundary fallback={<></>}>
        <FloatingPhone />
      </ErrorBoundary>
      <ErrorBoundary fallback={<></>}>
        <FloatingMusic />
      </ErrorBoundary>
      <ErrorBoundary fallback={<></>}>
        <MusicPlayerModal />
      </ErrorBoundary>
      <ErrorBoundary fallback={<></>}>
        <DriftBottleModal />
      </ErrorBoundary>
      <ErrorBoundary fallback={<></>}>
        <MsgNotificationToasts />
      </ErrorBoundary>
    </>
  );
}
